def solve(nums, k):
    if not nums:
        return 0
    min_val, max_val = min(nums), max(nums)
    bucket_range = 100
    num_buckets = (max_val - min_val) // bucket_range + 1
    buckets = [[] for _ in range(num_buckets)]

    for x in nums:
        idx = (x - min_val) // bucket_range
        buckets[idx].append(x)

    count = 0
    for bucket in buckets:
        count += len(bucket)
        if count >= k:
            remainder = k - (count - len(bucket))
            return sorted(bucket)[remainder - 1]

